std::string yes(bool b){return b?"true":"false";}
std::string join(const std::vector<std::string>& values){std::string result;for(const auto& value:values){if(!result.empty())result+=',';result+=value;}return result;}
o::ObjectRef array(o::Context& c,std::initializer_list<const char16_t*> values){auto result=c.array(static_cast<std::uint32_t>(values.size()));std::uint32_t i=0;for(auto value:values){auto n=std::to_string(i++);c.set(result,o::Key(std::u16string(n.begin(),n.end())),value);}return result;}
void getter(o::Context& c,o::ObjectRef object,const char16_t* key,std::function<o::Value()> get){auto f=c.function(u"get",[get=std::move(get)](auto&,auto,auto){return get();});c.define(object,key,o::Descriptor::access(f,{},true,true));}
o::Value bind(o::Context&,OptionFunctionBindings& bindings,FunctionRef fn){return bindings.bind(fn,{[](auto&,auto)->FunctionReceiver{return Missing{};},[](auto&,auto){return std::vector<std::any>{};},[](auto&,const auto&)->o::Value{return o::Undefined{};}});}
struct HandlerAccess:t::SubHandler {static FunctionList& list(t::SubHandler& h){auto p=&HandlerAccess::fallback_;return h.*p;}};
std::size_t fallbackCount(t::SubHandlers& h){std::size_t n=0;for(auto& item:HandlerAccess::list(*h.get("macro")))++n;return n;}
bool fallbackIdentity(t::SubHandlers& h,const FunctionRef& fn){auto& list=HandlerAccess::list(*h.get("macro"));auto i=list.begin();return i!=list.end()&&std::get<FunctionRef>(i.record()->item)==fn;}
std::string mapNames(t::SubHandlers& h){auto x=h.get("macro");return x?x->toString():"";}
std::string handlerKeys(t::SubHandlers& h){std::vector<std::string> result;auto i=h.keys();while(auto key=i.next())result.push_back(*key);return join(result);}
struct Factory:t::NodeFactory {std::vector<std::string>& trace;explicit Factory(std::vector<std::string>& trace):trace(trace){}void set(std::string_view kind,Property value)override{trace.push_back("set:"+std::string(kind));t::NodeFactory::set(kind,std::move(value));}};
std::string text(o::Value value){if(std::holds_alternative<o::Null>(value.data))return "N";if(auto p=std::get_if<std::u16string>(&value.data))return property_host::debugText(*p);return "?";}
std::string tagFields(const t::TagInfo& x){return property_host::debugText(x.env)+"|"+yes(x.taggable)+"|"+yes(x.defaultTags)+"|"+text(x.tag)+"|"+property_host::debugText(x.tagId)+"|"+text(x.tagFormat)+"|"+yes(x.noTag)+"|"+property_host::debugText(x.labelId);}
